public EntityLivingBase getThrower()
    {
        if (this.thrower == null && this.throwerName != null && this.throwerName.length() > 0)
        {
            this.thrower = this.world.getPlayerEntityByName(this.throwerName);
        }

        return this.thrower;
    }
